def soft_shadow(canvas, center, radius):
    size = 48
    image = Image.new("L", (size, size), 0)
    draw = ImageDraw.Draw(image)
    draw.ellipse((8, 15, 40, 32), fill=48)
    image = image.filter(ImageFilter.GaussianBlur(5))
    alpha = np.asarray(image).astype(np.float32) / 255.0
    x0 = round(center[0] - size/2)
    y0 = round(center[1] - size/2)
    for y in range(size):
        yy = y0 + y
        if not 0 <= yy < H:
            continue
        for x in range(size):
            xx = x0 + x
            if 0 <= xx < W and alpha[y, x] > 0:
                a = alpha[y, x]
                canvas[yy, xx] = np.clip(
                    canvas[yy, xx].astype(np.float32) * (1 - a) + np.array((25, 20, 17)) * a,
                    0, 255
                ).astype(np.uint8)


