def bread_pose(i, first, sprite_size):
    """Return center, angle, and clipping for one bread slice."""
    h = sprite_size[0]
    if first:
        if i < 3:
            return (96.0, 125.0), -3.0, None
        if i == 3:
            return (96.0, 122.0), -3.0, None
        if i == 4:
            return (97.0, 98.0), -2.0, None
        if i == 5:
            return (112.0, 75.0), 0.0, None
        if i == 6:
            return (126.0, 57.0), 0.0, None
