def main():
    frame0 = np.asarray(Image.open(ROOT / "first_frame.png").convert("RGB")).copy()
    assert frame0.shape == (H, W, 3)
    clean = make_clean_plate(frame0)
    left_sprite, right_sprite = make_bread_sprites(frame0)
    sprites = {
        "left": {a: rotate_rgba(left_sprite, a) for a in (-4, 0, 1, 3, 4)},
        "right": {a: rotate_rgba(right_sprite, a) for a in (-3, -2, 0)},
    }

    frames = []
    for i in range(N):
        if i == 0:
            frames.append(frame0.copy())
            continue

        canvas = clean.copy()
        wrist, angle, gap, bend = pose_for_frame(i)
        arm = draw_arm(wrist, angle, gap, bend)

        # Grounding shadow while bread is airborne.
        if 3 <= i <= 7:
            soft_shadow(canvas, (bread_pose(i, True, right_sprite.shape)[0][0] + 4, 145), 1.0)
        if 12 <= i <= 16:
            soft_shadow(canvas, (bread_pose(i, False, left_sprite.shape)[0][0] + 4, 145), 1.0)

        # Bread in the basket until each slice is picked.
        if i < 3:
            center, angle_b, clip = bread_pose(i, True, right_sprite.shape)
            paste_rgba(canvas, sprites["right"][-3], center, clip)
        if i < 12:
            center, angle_b, clip = bread_pose(i, False, left_sprite.shape)
            paste_rgba(canvas, sprites["left"][4], center, clip)

        # The first slice is already released while the arm travels for the second.
        if i >= 8:
            center, angle_b, clip = bread_pose(i, True, right_sprite.shape)
            paste_rgba(canvas, sprites["right"][0], center, clip)

        # Slice currently held by the gripper.
        if 3 <= i <= 7:
            center, angle_b, clip = bread_pose(i, True, right_sprite.shape)
            paste_rgba(canvas, sprites["right"][-2 if i == 4 else 0], center, clip)
        if 12 <= i <= 16:
            center, angle_b, clip = bread_pose(i, False, left_sprite.shape)
            paste_rgba(canvas, sprites["left"][3 if i == 13 else 0], center, clip)

        # The second slice remains in its slot for the closing frames.
        if i >= 17:
            center, angle_b, clip = bread_pose(i, False, left_sprite.shape)
            paste_rgba(canvas, sprites["left"][0], center, clip)

        # A faint displaced silhouette keeps the arm visually attached to the scene.
        shadow = arm.copy()
        shadow[..., :3] = (8, 10, 9)
        shadow[..., 3] = (shadow[..., 3].astype(np.float32) * 0.18).astype(np.uint8)
        composite_rgba(canvas, shadow, (4, 6), 1.0)
        composite_rgba(canvas, arm)
        frames.append(canvas)

    frames = np.asarray(frames, dtype=np.uint8)
    artifact_io.save(frames, ROOT)

    # Keep a compact review copy next to the required player assets.
    Image.fromarray(clean).save(ROOT / ".tmp" / "clean_plate.png")


if __name__ == "__main__":
    main()
